def kernel(W):
    G = W @ W.T / W.shape[1]
    dd = G.diagonal()
    return (G, np.maximum(dd[:, None] + dd - 2 * G, 0))

def vf(V):
    from itertools import combinations
    parts = [V, V * V, np.tanh(V), np.sin(V), np.arcsinh(V)]
    for mix in (0.5, 1, 2):
        plus = np.column_stack([V[:, i] + mix * V[:, j] for (i, j) in combinations(range(8), 2)])
        minus = np.column_stack([V[:, i] - mix * V[:, j] for (i, j) in combinations(range(8), 2)])
        parts.extend([np.tanh(plus) / 3, np.tanh(minus) / 3])
    for alpha in (0.15, 0.5, 1.0):
        parts.append(np.column_stack([V[:, i] / (1 + alpha * V[:, j] ** 2) for i in range(8) for j in range(8)]) / 3)
    parts.append(np.column_stack([V[:, i] * V[:, j] * V[:, k] for (i, j, k) in combinations(range(8), 3)]) / 3)
    return np.column_stack(parts)

def aff(p, key='v'):
    u = p['u']
    v = p[key]
    f = np.c_[np.ones(len(u)), u]
    i = np.arange(len(u))
    for _ in range(6):
        b = np.linalg.lstsq(f[i], v[i], rcond=None)[0]
        i = np.argsort(np.linalg.norm(f @ b - v, axis=1))[:int(0.85 * len(u))]
    return (b[0], b[1:])
